"use strict";(globalThis.webpackChunkaarati_sangrah=globalThis.webpackChunkaarati_sangrah||[]).push([[43780],{77653(a,e,n){n.r(e),n.d(e,{assets:()=>o,contentTitle:()=>h,default:()=>u,frontMatter:()=>s,metadata:()=>t,toc:()=>c});const t=JSON.parse('{"id":"katha/gauri-mahalaxmi-kahani","title":"\u091c\u094d\u092f\u0947\u0937\u094d\u0920\u093e\u0917\u094c\u0930\u0940\u091a\u0940 / \u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0940  \u0915\u0939\u093e\u0923\u0940","description":"\u091c\u094d\u092f\u0947\u0937\u094d\u0920\u093e\u0917\u094c\u0930\u0940\u091a\u0940 \u0915\u0939\u093e\u0923\u0940","source":"@site/docs/katha/gauri-mahalaxmi-kahani.md","sourceDirName":"katha","slug":"/jestha-gauri-kahani","permalink":"/jestha-gauri-kahani","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"slug":"/jestha-gauri-kahani"},"sidebar":"tutorialSidebar","previous":{"title":"\u0926\u093f\u0935\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u0905\u0935\u0938\u0947\u091a\u0940 \u0915\u0939\u093e\u0923\u0940","permalink":"/divyachya-avsechi-kahani"},"next":{"title":"\u0917\u094b\u092a\u0926\u094d\u092e\u093e\u0902\u091a\u0940 \u0915\u0939\u093e\u0923\u0940","permalink":"/gopdama-kahani"}}');var i=n(74848),r=n(28453);const s={slug:"/jestha-gauri-kahani"},h="\u091c\u094d\u092f\u0947\u0937\u094d\u0920\u093e\u0917\u094c\u0930\u0940\u091a\u0940 / \u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0940  \u0915\u0939\u093e\u0923\u0940",o={},c=[{value:"\u091c\u094d\u092f\u0947\u0937\u094d\u0920\u093e\u0917\u094c\u0930\u0940\u091a\u0940 \u0915\u0939\u093e\u0923\u0940",id:"\u091c\u094d\u092f\u0947\u0937\u094d\u0920\u093e\u0917\u094c\u0930\u0940\u091a\u0940-\u0915\u0939\u093e\u0923\u0940",level:2},{value:"\u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0940 \u0932\u094b\u0915\u0915\u0925\u093e",id:"\u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0940-\u0932\u094b\u0915\u0915\u0925\u093e",level:2}];function l(a){const e={h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...a.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(e.header,{children:(0,i.jsx)(e.h1,{id:"\u091c\u094d\u092f\u0947\u0937\u094d\u0920\u093e\u0917\u094c\u0930\u0940\u091a\u0940--\u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0940--\u0915\u0939\u093e\u0923\u0940",children:"\u091c\u094d\u092f\u0947\u0937\u094d\u0920\u093e\u0917\u094c\u0930\u0940\u091a\u0940 / \u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0940  \u0915\u0939\u093e\u0923\u0940"})}),"\n",(0,i.jsx)(e.h2,{id:"\u091c\u094d\u092f\u0947\u0937\u094d\u0920\u093e\u0917\u094c\u0930\u0940\u091a\u0940-\u0915\u0939\u093e\u0923\u0940",children:"\u091c\u094d\u092f\u0947\u0937\u094d\u0920\u093e\u0917\u094c\u0930\u0940\u091a\u0940 \u0915\u0939\u093e\u0923\u0940"}),"\n",(0,i.jsx)(e.p,{children:'\u0906\u091f\u092a\u093e\u091f \u0928\u0917\u0930 \u0939\u094b\u0924\u0947, \u0924\u093f\u0925\u0902 \u090f\u0915 \u0917\u0930\u0940\u092c \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923 \u0930\u093e\u0939\u093e\u0924 \u0939\u094b\u0924\u093e. \u092a\u0941\u0922\u0902 \u090f\u0915\u0947 \u0926\u093f\u0935\u0936\u0940 \u0915\u093e\u092f \u091d\u093e\u0932\u0902? \u092d\u093e\u0926\u094d\u0930\u092a\u0926 \u092e\u0939\u093f\u0928\u093e \u0906\u0932\u093e. \u0918\u0930\u094b\u0918\u0930 \u0932\u094b\u0915\u093e\u0902\u0928\u0940\u0902 \u0917\u094c\u0930\u0940 \u0906\u0923\u0932\u094d\u092f\u093e. \u0930\u0938\u094d\u0924\u094b\u0930\u0938\u094d\u0924\u0940\u0902 \u092c\u093e\u092f\u0915\u093e \u0926\u0943\u0937\u094d\u091f\u0940\u0932\u093e \u092a\u0921\u0942\u0902 \u0932\u093e\u0917\u0932\u094d\u092f\u093e. \u0918\u0902\u091f\u093e \u0935\u093e\u091c\u0942\u0902 \u0932\u093e\u0917\u0932\u094d\u092f\u093e. \u0939\u0947\u0902 \u0924\u094d\u092f\u093e \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u091a\u094d\u092f\u093e \u092e\u0941\u0932\u093e\u0902\u0928\u0940\u0902 \u092a\u093e\u0939\u093f\u0932\u0902. \u092e\u0941\u0932\u0902 \u0918\u0930\u0940 \u0906\u0932\u0940\u0902. \u0906\u0908\u0932\u093e \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0902, \u201c\u0906\u0908, \u0906\u0908, \u0906\u092a\u0932\u094d\u092f\u093e \u0918\u0930\u0940 \u0917\u094c\u0930\u0940 \u0906\u0923."\n\u0906\u0908 \u092e\u094d\u0939\u0923\u093e\u0932\u0940, \u201c\u092c\u093e\u0933\u093e\u0902\u0928\u094b \u0917\u094c\u0930 \u0906\u0923\u0942\u0928 \u0915\u093e\u092f \u0915\u0930\u0942\u0902? \u0924\u093f\u091a\u0940 \u092a\u0941\u091c\u093e\u092a\u0924\u094d\u0930\u0940 \u0915\u0947\u0932\u0940 \u092a\u093e\u0939\u093f\u091c\u0947, \u0918\u093e\u0935\u0928-\u0918\u093e\u091f\u0932\u094d\u092f\u093e\u091a\u093e \u0928\u0948\u0935\u0947\u0926\u094d\u092f \u0926\u093e\u0916\u0935\u0932\u093e \u092a\u093e\u0939\u093f\u091c\u0947 \u0906\u0923\u093f \u0906\u092a\u0932\u094d\u092f\u093e \u0918\u0930\u093e\u0902\u0924 \u0924\u0930 \u0915\u093e\u0902\u0939\u0940\u0902 \u0928\u093e\u0939\u0940\u0902. \u0924\u0941\u092e\u094d\u0939\u0940\u0902 \u092c\u093e\u092c\u093e\u0902\u091c\u0935\u0933 \u091c\u093e, \u092c\u093e\u091c\u093e\u0930\u093e\u0902\u0924\u0932\u0902 \u0938\u093e\u092e\u093e\u0928 \u0906\u0923\u093e\u092f\u0932\u093e \u0938\u093e\u0902\u0917\u093e. \u0938\u093e\u092e\u093e\u0928 \u0906\u0923\u0932\u0902 \u092e\u094d\u0939\u0923\u091c\u0947 \u0917\u094c\u0930 \u0906\u0923\u0940\u0928\u0964\u201d \u092e\u0941\u0932\u0947\u0902 \u0924\u093f\u0925\u0942\u0928 \u0909\u0920\u0932\u0940\u0902, \u092c\u093e\u092a\u093e\u0915\u0921\u0947 \u0906\u0932\u0940\u0902 \u201c\u092c\u093e\u092c\u093e, \u092c\u093e\u092c\u093e, \u092c\u093e\u091c\u093e\u0930\u093e\u0902\u0924 \u091c\u093e. \u0918\u093e\u0935\u0928-\u0918\u093e\u091f\u0932\u094d\u092f\u093e\u091a\u0902 \u0938\u093e\u092e\u093e\u0928 \u0906\u0923\u093e. \u092e\u094d\u0939\u0923\u091c\u0947 \u0906\u0908 \u0917\u094c\u0930 \u0906\u0923\u0940\u0932\u0964\u201d \u092c\u093e\u092c\u093e\u0928\u0902 \u0918\u0930\u093e\u0902\u0924 \u091a\u094c\u0915\u0936\u0940 \u0915\u0947\u0932\u0940. \u092e\u0941\u0932\u093e\u0902\u091a\u093e \u0928\u093e\u0926 \u0910\u0915\u0932\u093e. \u092e\u0928\u093e\u0902\u0924 \u092b\u093e\u0930 \u0926\u0941\u0903\u0916\u0940 \u091d\u093e\u0932\u093e \u0938\u094b\u0928\u094d\u092f\u093e\u0938\u093e\u0930\u0916\u0940 \u092e\u0941\u0932\u0902 \u0906\u0939\u0947\u0924, \u092a\u0923 \u0924\u094d\u092f\u093e\u0902\u091a \u0939\u091f\u094d\u091f \u092a\u0941\u0930\u0935\u0924 \u0928\u093e\u0939\u0940\u0902. \u0917\u0930\u093f\u092c\u0940\u092a\u0941\u0922\u0902 \u0909\u092a\u093e\u092f \u0928\u093e\u0939\u0940\u0902. \u092e\u093e\u0917\u093e\u092f\u0932\u093e \u091c\u093e\u0935\u0902 \u0924\u0930 \u092e\u093f\u0933\u0924 \u0928\u093e\u0939\u0940\u0902. \u0924\u094d\u092f\u093e\u092a\u0947\u0915\u094d\u0937\u093e \u092e\u0930\u0923 \u092c\u0930\u0902. \u092e\u094d\u0939\u0923\u0942\u0928 \u0909\u0920\u0932\u093e, \u0926\u0947\u0935\u093e\u091a\u093e \u0927\u0902\u0935\u093e \u0915\u0947\u0932\u093e. \u0924\u0933\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u092a\u093e\u0933\u0940\u0902 \u0917\u0947\u0932\u093e. \u091c\u0940\u0935 \u0926\u094d\u092f\u093e\u0935\u093e \u092e\u094d\u0939\u0923\u0942\u0928 \u0928\u093f\u0936\u094d\u091a\u092f \u0915\u0947\u0932\u093e, \u0905\u0930\u094d\u0927\u094d\u092f\u093e \u0935\u093e\u091f\u0947\u0935\u0930 \u0917\u0947\u0932\u093e. \u0907\u0924\u0915\u094d\u092f\u093e\u0902\u0924 \u0938\u0902\u0927\u094d\u092f\u093e\u0915\u093e\u0933 \u091d\u093e\u0932\u0940. \u091c\u0935\u0933\u091a \u090f\u0915 \u092e\u094d\u0939\u093e\u0924\u093e\u0930\u0940 \u0938\u0935\u093e\u0936\u0940\u0923\u0902 \u092d\u0947\u091f\u0932\u0940. \u0924\u093f\u0928\u0902 \u0924\u094d\u092f\u093e\u091a\u0940 \u091a\u093e\u0939\u0942\u0932 \u0910\u0915\u0932\u0940. \u0915\u094b\u0923 \u092e\u094d\u0939\u0923\u0942\u0928 \u0935\u093f\u091a\u093e\u0930\u0932\u0902. \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0928\u0902 \u0939\u0915\u0940\u0915\u0924 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0940. \u092e\u094d\u0939\u093e\u0924\u093e\u0930\u0940\u0928\u0902 \u0938\u092e\u093e\u0927\u093e\u0928 \u0915\u0947\u0932\u0902. \u092c\u094b\u0927\u093e\u091a\u094d\u092f\u093e \u091a\u093e\u0930 \u0917\u094b\u0937\u094d\u091f\u0940 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u094d\u092f\u093e.   \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0928\u0902 \u092e\u094d\u0939\u093e\u0924\u093e\u0930\u0940\u0932\u093e \u0918\u0930\u0940\u0902 \u0906\u0923\u0932\u0902. \u092c\u093e\u092f\u0915\u094b\u0928\u0902 \u0926\u093f\u0935\u093e \u0932\u093e\u0935\u0932\u093e, \u091a\u094c\u0915\u0936\u0940 \u0915\u0947\u0932\u0940. \u092a\u093e\u0939\u0941\u0923\u094d\u092f\u093e\u092c\u093e\u0908 \u0915\u094b\u0923 \u0906\u0923\u0932\u094d\u092f\u093e \u092e\u094d\u0939\u0923\u0942\u0928 \u0935\u093f\u091a\u093e\u0930\u0932\u0902. \u0928\u0935\u0930\u094d\u092f\u093e\u0928\u0902 \u0906\u091c\u0940 \u092e\u094d\u0939\u0923\u0942\u0928 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0902. \u092c\u093e\u092f\u0915\u094b \u0918\u0930\u093e\u0902\u0924 \u0917\u0947\u0932\u0940. \u0906\u0902\u092c\u093f\u0932\u0940\u0915\u0930\u093f\u0924\u093e\u0902 \u0915\u0923\u094d\u092f\u093e \u092a\u093e\u0939\u0942\u0902 \u0932\u093e\u0917\u0932\u0940, \u0924\u094b \u092e\u0921\u0915\u0902 \u0906\u092a\u0932\u0902 \u0915\u0923\u094d\u092f\u093e\u0902\u0928\u0940\u0902 \u092d\u0930\u0932\u0947\u0932\u0902 \u0926\u0943\u0937\u094d\u091f\u0940\u0938 \u092a\u0921\u0932\u0902. \u0924\u093f\u0932\u093e \u092e\u094b\u0920\u0902 \u0928\u0935\u0932 \u0935\u093e\u091f\u0932\u0902. \u0939\u0940 \u0917\u094b\u0937\u094d\u091f \u0924\u093f\u0928\u0902 \u0906\u092a\u0932\u094d\u092f\u093e \u0928\u0935\u0930\u094d\u092f\u093e\u0932\u093e \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0940. \u0924\u094d\u092f\u093e\u0932\u093e \u092e\u094b\u0920\u093e \u0906\u0928\u0902\u0926 \u091d\u093e\u0932\u093e. \u092a\u0941\u0922\u0902 \u092a\u0941\u0937\u094d\u0915\u0933 \u092a\u0947\u091c \u0915\u0947\u0932\u0940, \u0938\u0917\u0933\u094d\u092f\u093e\u0902\u0928\u0940\u0902 \u092a\u094b\u091f\u092d\u0930 \u0916\u093e\u0932\u094d\u0932\u0940. \u0938\u0917\u0933\u0940\u0902\u091c\u0923\u0902 \u0906\u0928\u0902\u0926\u093e\u0928\u0902 \u0928\u093f\u091c\u0932\u0940\u0902.   \u0938\u0915\u093e\u0933 \u091d\u093e\u0932\u0940, \u0924\u0936\u0940 \u092e\u094d\u0939\u093e\u0924\u093e\u0930\u0940\u0928\u0902 \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0938 \u0939\u093e\u0902\u0915 \u092e\u093e\u0930\u0932\u0940, \u201c\u092e\u0941\u0932\u093e \u092e\u0941\u0932\u093e, \u092e\u0932\u093e \u0928\u094d\u0939\u093e\u090a \u0918\u093e\u0932\u093e\u092f\u0932\u093e \u0938\u093e\u0902\u0917\u0964\u201d \u092e\u094d\u0939\u0923\u0942\u0928 \u092e\u094d\u0939\u0923\u093e\u0932\u0940, \u201c\u0918\u093e\u0935\u0928\u0918\u093e\u091f\u0932\u0902 \u0926\u0947\u0935\u093e\u0932\u093e \u0915\u0930 \u0928\u093e\u0939\u0940\u0902 \u0915\u093e\u0902\u0939\u0940\u0902 \u092e\u094d\u0939\u0923\u0942\u0902 \u0928\u0915\u094b. \u0930\u0921 \u0915\u093e\u0939\u0940 \u0917\u093e\u090a \u0928\u0915\u094b." \u092c\u094d\u0930\u093e\u092e\u094d\u0939\u0923 \u0924\u0938\u093e\u091a \u0909\u0920\u0932\u093e, \u0918\u0930\u093e\u0924 \u0917\u0947\u0932\u093e. \u092c\u093e\u092f\u0915\u094b\u0932\u093e \u0939\u093e\u0902\u0915 \u092e\u093e\u0930\u0932\u0940, "\u0905\u0917 \u0905\u0917 \u0910\u0915\u0932\u0938\u0902 \u0915\u093e? \u0906\u091c\u0940\u092c\u093e\u0908\u0932\u093e \u0928\u094d\u0939\u093e\u090a\u0902 \u0918\u093e\u0932" \u0905\u0938\u0902 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0902. \u0906\u092a\u0923 \u0909\u0920\u0942\u0928 \u092d\u093f\u0915\u094d\u0937\u0947\u0932\u093e \u0917\u0947\u0932\u093e. \u092d\u093f\u0915\u094d\u0937\u093e \u092a\u0941\u0937\u094d\u0915\u0933 \u092e\u093f\u0933\u093e\u0932\u0940. \u0938\u092a\u093e\u091f\u0942\u0928 \u0917\u0942\u0933 \u092e\u093f\u0933\u093e\u0932\u093e. \u0938\u0917\u0933\u0902 \u0938\u093e\u092e\u093e\u0928 \u0906\u0923\u0932\u0902. \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0932\u093e \u0906\u0928\u0902\u0926 \u091d\u093e\u0932\u093e.   \u092c\u093e\u092f\u0915\u094b\u0928\u0902 \u0938\u0930\u094d\u0935 \u0938\u094d\u0935\u092f\u0902\u092a\u093e\u0915 \u0915\u0947\u0932\u093e. \u092e\u0941\u0932\u093e\u0902\u092c\u093e\u0933\u093e\u0902\u0938\u0941\u0926\u094d\u0927\u093e\u0902 \u092a\u094b\u091f\u092d\u0930 \u091c\u0947\u0935\u0932\u0940\u0902. \u092e\u094d\u0939\u093e\u0924\u093e\u0930\u0940\u0928\u0902 \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0932\u093e \u0939\u093e\u0902\u0915 \u092e\u093e\u0930\u0932\u0940. \u201c\u0909\u0926\u094d\u092f\u093e\u0902 \u091c\u0947\u0935\u093e\u092f\u0932\u093e \u0916\u0940\u0930 \u0915\u0930\u201d \u092e\u094d\u0939\u0923\u0942\u0928 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0902, \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923 \u092e\u094d\u0939\u0923\u093e\u0932\u093e, \u201c\u0906\u091c\u0940, \u0906\u091c\u0940, \u0926\u0942\u0927 \u0915\u094b\u0920\u0942\u0928 \u0906\u0923\u0942?" \u0924\u0936\u0940 \u092e\u094d\u0939\u093e\u0924\u093e\u0930\u0940 \u092e\u094d\u0939\u0923\u093e\u0932\u0940\u0902, \u201c\u0924\u0942\u0902 \u0915\u093e\u0902\u0939\u0940\u0902 \u0915\u093e\u0933\u091c\u0940 \u0915\u0930\u0942\u0902 \u0928\u0915\u094b. \u0906\u0924\u093e\u0902 \u0909\u0920, \u0906\u0923\u093f \u0924\u0941\u0932\u093e \u091c\u093f\u0924\u0915\u094d\u092f\u093e \u0917\u093e\u0908 \u092e\u094d\u0939\u0936\u0940 \u092a\u093e\u0939\u093f\u091c\u0947 \u0905\u0938\u0924\u0940\u0932 \u0924\u093f\u0924\u0915\u0947 \u0916\u0941\u0902\u091f\u0947 \u092a\u0942\u0930. \u0924\u093f\u0924\u0915\u094d\u092f\u093e\u0902\u0928\u093e \u0926\u093e\u0935\u0940\u0902 \u092c\u093e\u0902\u0927. \u0938\u0902\u0927\u094d\u092f\u093e\u0915\u093e\u0933\u0940 \u0917\u094b\u0930\u091c \u092e\u0941\u0939\u0942\u0930\u094d\u0924\u093e\u0935\u0930 \u0917\u093e\u0908-\u092e\u094d\u0939\u0936\u0940\u0902\u091a\u0940 \u0928\u093e\u0902\u0935\u0902 \u0918\u0947\u090a\u0928 \u0939\u093e\u0902\u0915\u093e\u0902 \u092e\u093e\u0930, \u092e\u094d\u0939\u0923\u091c\u0947 \u0924\u094d\u092f\u093e \u092f\u0947\u0924\u0940\u0932 \u0924\u0941\u091d\u093e \u0917\u094b\u0920\u093e \u092d\u0930\u0947\u0932. \u0924\u094d\u092f\u093e\u0902\u091a\u0902 \u0926\u0942\u0927 \u0915\u093e\u0922." \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0928\u0902 \u0924\u0938\u0902 \u0915\u0947\u0932\u0902.   \u0917\u093e\u0908\u092e\u094d\u0939\u0936\u0940\u0902\u0928\u093e \u0939\u093e\u0902\u0915\u093e \u092e\u093e\u0930\u0932\u094d\u092f\u093e \u0924\u094d\u092f\u093e \u0935\u093e\u0902\u0938\u0930\u093e\u0902\u0938\u0941\u0926\u094d\u0927\u093e\u0902 \u0927\u093e\u0902\u0935\u0924 \u0906\u0932\u094d\u092f\u093e. \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u091a\u093e \u0917\u094b\u0920\u093e \u0917\u093e\u0908\u092e\u094d\u0939\u0936\u0940\u0902\u0928\u0940\u0902 \u092d\u0930\u0942\u0928 \u0917\u0947\u0932\u093e. \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0928\u0902 \u0924\u094d\u092f\u093e\u0902\u091a\u0902 \u0926\u0942\u0927 \u0915\u093e\u0922\u0932\u0902, \u0926\u0941\u0938\u0930\u094d\u092f\u093e \u0926\u093f\u0935\u0936\u0940\u0902 \u0916\u0940\u0930 \u0915\u0947\u0932\u0940. \u0938\u0902\u0927\u094d\u092f\u093e\u0915\u093e\u0933 \u091d\u093e\u0932\u0940, \u0924\u0936\u0940 \u092e\u094d\u0939\u093e\u0924\u093e\u0930\u0940 \u092e\u094d\u0939\u0923\u093e\u0932\u0940," \u092e\u0941\u0932\u093e \u092e\u0941\u0932\u093e, \u092e\u0932\u093e \u0906\u0924\u093e\u0902 \u092a\u094b\u0902\u091a\u0924\u0940 \u0915\u0930." \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923 \u092e\u094d\u0939\u0923\u0942\u0902 \u0932\u093e\u0917\u0932\u093e, \u201c\u0906\u091c\u0940 \u0906\u091c\u0940, \u0924\u0941\u092e\u091a\u094d\u092f\u093e \u0915\u0943\u092a\u0947\u0928\u0902 \u092e\u0932\u093e \u0938\u0917\u0933 \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u091d\u093e\u0932\u0902, \u0906\u0924\u093e\u0902 \u0924\u0941\u092e\u094d\u0939\u093e\u0902\u0932\u093e \u092a\u094b\u0902\u091a\u0924\u094d\u092f\u093e \u0915\u0936\u093e \u0915\u0930\u0942\u0902? \u0924\u0941\u092e\u094d\u0939\u0940 \u0917\u0947\u0932\u093e\u0902 \u092e\u094d\u0939\u0923\u091c\u0947 \u0939\u0947\u0902 \u0938\u0930\u094d\u0935 \u0928\u093e\u0939\u0940\u0938\u0902 \u0939\u094b\u0908\u0932."\n\u092e\u094d\u0939\u093e\u0924\u093e\u0930\u0940 \u092e\u094d\u0939\u0923\u093e\u0932\u0940. \u201c\u0924\u0942\u0902 \u0915\u093e\u0902\u0939\u0940\u0902 \u0918\u093e\u092c\u0930\u0942\u0902 \u0928\u0915\u094b, \u092e\u093e\u091d\u094d\u092f\u093e \u0906\u0936\u0940\u0930\u094d\u0935\u093e\u0926\u093e\u0928\u0902 \u0924\u0941\u0932\u093e \u0915\u093e\u0902\u0939\u0940\u0902 \u0915\u092e\u0940 \u092a\u0921\u0923\u093e\u0930 \u0928\u093e\u0939\u0940\u0902. \u091c\u094d\u092f\u0947\u0937\u094d\u0920\u093e\u0917\u094c\u0930 \u092e\u094d\u0939\u0923\u0924\u093e\u0924 \u0924\u0940 \u092e\u0940\u091a. \u0906\u091c \u092e\u0932\u093e \u092a\u094b\u0902\u091a\u0924\u0940 \u0915\u0930\u0964\u201d \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923 \u092e\u094d\u0939\u0923\u093e\u0932\u093e, \u201c\u0939\u0947\u0902 \u0926\u093f\u0932\u0947\u0932\u0902 \u0905\u0938\u0902\u091a \u0935\u093e\u0922\u093e\u0935\u0902 \u0905\u0938\u093e \u0915\u093e\u0902\u0939\u0940\u0902 \u0909\u092a\u093e\u092f \u0938\u093e\u0902\u0917\u093e\u0964\u201d \u0917\u094c\u0930\u0940\u0928\u0902 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0947\u0902, "\u0924\u0941\u0932\u093e \u092f\u0947\u0924\u093e\u0902\u0928\u093e \u0935\u093e\u0933\u0942 \u0926\u0947\u0908\u0928. \u0924\u0940 \u0938\u093e\u0930\u094d\u092f\u093e \u0918\u0930\u092d\u0930 \u091f\u093e\u0915. \u0939\u093e\u0902\u0921\u094d\u092f\u093e\u0935\u0930 \u091f\u093e\u0915, \u092e\u0921\u0915\u094d\u092f\u093e\u0935\u0930 \u091f\u093e\u0902\u0915, \u092a\u0947\u091f\u0940\u0902\u0924 \u091f\u093e\u0915, \u092b\u0921\u0924\u093e\u0933\u093e\u0902\u0924 \u091f\u093e\u0915, \u0917\u094b\u0920\u094d\u092f\u093e\u0902\u0924 \u091f\u093e\u0915. \u0905\u0938\u0902 \u0915\u0947\u0932\u0902 \u092e\u094d\u0939\u0923\u091c\u0947 \u0915\u0927\u0940\u0902 \u0915\u092e\u0940 \u0939\u094b\u0923\u093e\u0930 \u0928\u093e\u0939\u0940\u0902" \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0928\u0902 \u092c\u0930\u0902 \u092e\u094d\u0939\u091f\u0932\u0902. \u0924\u093f\u091a\u0940 \u092a\u0942\u091c\u093e \u0915\u0947\u0932\u0940.   \u0917\u094c\u0930 \u0906\u092a\u0932\u0940 \u092a\u094d\u0930\u0938\u0928\u094d\u0928 \u091d\u093e\u0932\u0940. \u0924\u093f\u0928\u0902 \u0906\u092a\u0932\u0902 \u0935\u094d\u0930\u0924 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0902, \u092d\u093e\u0926\u0935\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u092e\u0939\u093f\u0928\u094d\u092f\u093e\u0924 \u0924\u0933\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u092a\u093e\u0933\u0940\u0902 \u091c\u093e\u0935\u0902, \u0926\u094b\u0928 \u0916\u0921\u0947 \u0918\u0930\u0940\u0902 \u0906\u0923\u093e\u0935\u0947. \u090a\u0928 \u092a\u093e\u0923\u094d\u092f\u093e\u0928\u0902 \u0927\u0941\u0935\u093e\u0935\u0947. \u091c\u094d\u092f\u0947\u0937\u094d\u0920\u093e\u0917\u094c\u0930 \u0935 \u0915\u0928\u093f\u0937\u094d\u0920\u093e\u0917\u094c\u0930 \u092e\u094d\u0939\u0923\u0942\u0928 \u0924\u094d\u092f\u093e\u0902\u091a\u0940 \u0938\u094d\u0925\u093e\u092a\u0928\u093e \u0915\u0930\u093e\u0935\u0940. \u0924\u094d\u092f\u093e\u0902\u091a\u0940 \u092a\u0942\u091c\u093e \u0915\u0930\u093e\u0935\u0940. \u0926\u0941\u0938\u0930\u0947 \u0926\u093f\u0935\u0936\u0940\u0902 \u0918\u093e\u0935\u0928\u0917\u094b\u0921\u0902, \u0924\u093f\u0938\u0930\u0947 \u0926\u093f\u0935\u0936\u0940 \u0916\u0940\u0930 \u092a\u094b\u0933\u0940\u091a\u093e \u0928\u0948\u0935\u0947\u0926\u094d\u092f \u0926\u093e\u0916\u0935\u093e\u0935\u093e. \u0938\u0935\u093e\u0937\u094d\u0923\u0940\u091a\u0940 \u0913\u091f\u0940 \u092d\u0930\u093e\u0935\u0940. \u091c\u0947\u0935\u0942 \u0918\u093e\u0932\u093e\u0935\u0902. \u0938\u0902\u0927\u094d\u092f\u093e\u0915\u093e\u0933\u0940\u0902 \u0939\u0933\u0926\u0915\u0941\u0902\u0915\u0942 \u0935\u093e\u0939\u0942\u0928 \u092c\u094b\u0933\u0935\u0923 \u0915\u0930\u093e\u0935\u0940. \u092e\u094d\u0939\u0923\u091c\u0947 \u0924\u094d\u092f\u093e\u0932\u093e \u0905\u0915\u094d\u0937\u092f \u0938\u0941\u0916 \u092e\u093f\u0933\u0947\u0932. \u0938\u0902\u0924\u0924 \u0938\u0902\u092a\u0924 \u092e\u093f\u0933\u0947\u0932.   \u0939\u0940 \u0938\u093e\u0902\u0920\u093e\u0902 \u0909\u0924\u094d\u0924\u0930\u093e\u0902\u091a\u0940 \u0915\u0939\u093e\u0923\u0940, \u092a\u093e\u0902\u091a\u093e\u0902 \u0909\u0924\u094d\u0924\u0930\u0940\u0902, \u0926\u0947\u0935\u093e\u091a\u094d\u092f\u093e\n\u0926\u093e\u0930\u0940\u0902, \u0917\u093e\u0908\u091a\u094d\u092f\u093e \u0917\u094b\u0920\u0940, \u092a\u093f\u0902\u092a\u0933\u093e\u091a\u094d\u092f\u093e \u092a\u093e\u0930\u0940\u0902, \u0938\u0941\u092b\u0933 \u0938\u0902\u092a\u0942\u0930\u094d\u0923.'}),"\n",(0,i.jsx)(e.h2,{id:"\u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0940-\u0932\u094b\u0915\u0915\u0925\u093e",children:"\u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0940 \u0932\u094b\u0915\u0915\u0925\u093e"}),"\n",(0,i.jsx)(e.p,{children:"\u092a\u0941\u0930\u093e\u0923\u093e\u0924 \u0909\u0932\u094d\u0932\u0947\u0916 \u0906\u0922\u0933\u0924 \u0928\u0938\u0932\u093e \u0924\u0930\u0940 \u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0940 \u0932\u094b\u0915\u0915\u0925\u093e \u092a\u094d\u0930\u0938\u093f\u0926\u094d\u0927 \u0906\u0939\u0947. \u090f\u0915\u093e \u0930\u093e\u091c\u093e\u0932\u093e \u0926\u094b\u0928 \u0930\u093e\u0923\u094d\u092f\u093e \u0905\u0938\u0924\u093e\u0924. \u090f\u0915 \u0906\u0935\u0921\u0924\u0940 \u0906\u0923\u093f \u0926\u0941\u0938\u0930\u0940 \u0928\u093e\u0935\u0921\u0924\u0940. \u0905\u0930\u094d\u0925\u093e\u0924, \u0906\u0935\u0921\u0924\u0940 \u0930\u093e\u0923\u0940 \u0930\u093e\u091c\u093e\u0938\u094b\u092c\u0924 \u0930\u093e\u091c\u0935\u093e\u0921\u092f\u093e\u0924 \u0930\u093e\u0939\u0924 \u0905\u0938\u0924\u0947, \u0924\u0930 \u0928\u093e\u0935\u0921\u0924\u0940 \u0917\u093e\u0935\u093e\u092c\u093e\u0939\u0947\u0930 \u0930\u093e\u0939\u0924 \u0905\u0938\u0924\u0947. \u090f\u0915\u0947 \u0926\u093f\u0935\u0936\u0940 \u0924\u094d\u092f\u093e \u0930\u093e\u091c\u093e\u091a\u094d\u092f\u093e \u0926\u094b\u0928 \u092e\u093e\u0935\u0936\u094d\u092f\u093e \u0924\u094d\u092f\u093e\u0932\u093e \u092d\u0947\u091f\u0923\u094d\u092f\u093e\u0938\u093e\u0920\u0940 \u092f\u0947\u0924\u093e\u0924. \u0905\u0930\u094d\u0925\u093e\u0924, \u092a\u0939\u093f\u0932\u094d\u092f\u093e\u0902\u0926\u093e \u0924\u094d\u092f\u093e \u0930\u093e\u091c\u0935\u093e\u0921\u092f\u093e\u0924 \u091c\u093e\u0924\u093e\u0924. \u092e\u093e\u0924\u094d\u0930 \u0906\u0935\u0921\u0924\u0940 \u0930\u093e\u0923\u0940 \u0924\u094d\u092f\u093e\u0902\u0928\u093e \u0906\u092a\u0932\u094d\u092f\u093e \u0918\u0930\u093e\u0924 \u0918\u0947\u0924 \u0928\u093e\u0939\u0940. \u0924\u094d\u092f\u093e \u0926\u094b\u0918\u0940 \u092a\u0941\u0928\u094d\u0939\u093e \u0928\u093e\u0935\u0921\u0924\u094d\u092f\u093e \u0930\u093e\u0923\u0940\u0915\u0921\u0947 \u091c\u093e\u0924\u093e\u0924. \u0924\u093f\u091a\u0940 \u0917\u0930\u093f\u092c\u0940 \u0905\u0938\u0924\u0947 \u0924\u0930\u0940 \u0924\u0940 \u0924\u094d\u092f\u093e \u0926\u094b\u0918\u0940\u0902\u091a\u0902\u0939\u0940 \u0924\u0940 \u091b\u093e\u0928 \u092a\u094d\u0930\u0915\u093e\u0930\u0947 \u0906\u0926\u0930\u093e\u0924\u093f\u0925\u094d\u092f \u0915\u0930\u0924\u0947. \u0924\u094d\u092f\u093e \u0926\u094b\u0918\u0940\u0939\u0940 \u0924\u093f\u091a\u094d\u092f\u093e\u0935\u0930 \u0916\u0942\u0936 \u0939\u094b\u0924\u093e\u0924 \u0906\u0923\u093f \u0924\u093f\u0932\u093e \u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0902 \u0935\u094d\u0930\u0924 \u0915\u0930\u093e\u092f\u0932\u093e \u0938\u093e\u0902\u0917\u0924\u093e\u0924. \u0928\u093e\u0935\u0921\u0924\u0940 \u0930\u093e\u0923\u0940 \u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0902 \u0935\u094d\u0930\u0924 \u0915\u0930\u0924\u0947 \u0906\u0923\u093f \u0924\u094d\u092f\u093e\u0924\u0942\u0928 \u0924\u093f\u091a\u094d\u092f\u093e \u0918\u0930\u0940 \u0910\u0936\u094d\u0935\u0930\u094d\u092f \u092f\u0947\u0924\u0902. \u0924\u0930 \u0906\u0935\u0921\u0924\u0940\u091a\u094d\u092f\u093e \u0918\u0930\u0940 \u0926\u093e\u0930\u093f\u0926\u094d\u0930\u092f \u092f\u0947\u0924\u0902. \u092a\u0941\u0922\u0947 \u0930\u093e\u091c\u093e\u0939\u0940 \u0924\u094d\u092f\u093e \u0928\u093e\u0935\u0921\u0924\u094d\u092f\u093e \u0930\u093e\u0923\u0940\u0915\u0921\u0947 \u092f\u0947\u0924\u094b. \u0938\u092e\u0943\u0926\u094d\u0927\u0940 \u0906\u0923\u093f \u0938\u0941\u0916 \u0926\u0947\u0923\u093e\u0930\u0902 \u0905\u0938\u0902 \u0939\u0947 \u0935\u094d\u0930\u0924 \u092e\u094d\u0939\u0923\u0942\u0928 \u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0902 \u092a\u0942\u091c\u0928 \u0915\u0947\u0932\u0902 \u091c\u093e\u0924\u0902."}),"\n",(0,i.jsx)("span",{class:"index-text",children:" jestha gauri kahani katha, mahalaxmi kahani"})]})}function u(a={}){const{wrapper:e}={...(0,r.R)(),...a.components};return e?(0,i.jsx)(e,{...a,children:(0,i.jsx)(l,{...a})}):l(a)}},28453(a,e,n){n.d(e,{R:()=>s,x:()=>h});var t=n(96540);const i={},r=t.createContext(i);function s(a){const e=t.useContext(r);return t.useMemo(function(){return"function"==typeof a?a(e):{...e,...a}},[e,a])}function h(a){let e;return e=a.disableParentContext?"function"==typeof a.components?a.components(i):a.components||i:s(a.components),t.createElement(r.Provider,{value:e},a.children)}}}]);
